"""Curated, general-purpose medical communication phrase library (fictional / non-diagnostic).

Fields mirror the Typesense `communication_phrases` schema. `safety_priority` 0-10: higher means
the phrase must stay reachable (urgent phrases are never filtered out by personalization).
"""
from __future__ import annotations

from typing import Any


def _p(pid: str, text: str, category: str, tags: str, syn: str = "", region: str = "",
       rtype: str = "answer", icon: str = "", prio: int = 1) -> dict[str, Any]:
    return {
        "id": pid,
        "text": text,
        "language": "en",
        "category": category,
        "synonyms": [s.strip() for s in syn.split(",") if s.strip()],
        "intent_tags": [t.strip() for t in tags.split(",") if t.strip()],
        "anatomical_region": region or "none",
        "response_type": rtype,
        "pictogram_id": icon or "message",
        "safety_priority": prio,
    }


